insert into public.referencias (id, citacao, url, como_foi_lida) values ('R1', 'AMARO, G. B.; SILVA, D. M.; MARINHO, A. G.; NASCIMENTO, W. M. Recomendações técnicas para o cultivo de hortaliças em agricultura familiar. Brasília, DF: Embrapa Hortaliças, 2007. (Circular Técnica, 47).', 'https://core.ac.uk/download/15428632.pdf', 'Lido no texto original (Tabela 1, p. 4; p. 2-10)') on conflict (id) do update set citacao = excluded.citacao, url = excluded.url, como_foi_lida = excluded.como_foi_lida;
insert into public.referencias (id, citacao, url, como_foi_lida) values ('R2', 'CLEMENTE, F. M. V. T. (ed. téc.). Produção de hortaliças para agricultura familiar. Brasília, DF: Embrapa Hortaliças, 2015. 108 p. ISBN 978-85-7035-412-9.', 'https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/1020866/1/Producao-de-Hortalicas-para-a-Agricultura-Familiar.pdf', 'Cap. 1-2 lidos no original; Tabela 8 (épocas por região, p. 55-57) e tabelas de adubação lidas por resumo: conferir') on conflict (id) do update set citacao = excluded.citacao, url = excluded.url, como_foi_lida = excluded.como_foi_lida;
insert into public.referencias (id, citacao, url, como_foi_lida) values ('R3', 'CLEMENTE, F. M. V. T.; HABER, L. L. (ed. téc.). Horta em pequenos espaços. Brasília, DF: Embrapa Hortaliças, 2012 (4ª impr. 2017). 56 p. ISBN 978-85-7035-047-3.', 'https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/927690/1/HORTA-EM-PEQUENOS-ESPACOS-4-IMP-2017.pdf', 'Lido no original; Tabela 2 (p. 35-36) não extraída (imagem)') on conflict (id) do update set citacao = excluded.citacao, url = excluded.url, como_foi_lida = excluded.como_foi_lida;
insert into public.referencias (id, citacao, url, como_foi_lida) values ('R4', 'RICCI, M. S. F. Cultivo doméstico do tomateiro em ambiente protegido de baixo custo. Seropédica: Embrapa Agrobiologia, 2018. 21 p. (Documentos, 309).', 'https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/1100367/1/SerieDoc309CULTIVODOMESTICOTOMATEIRO.pdf', 'Lido no original') on conflict (id) do update set citacao = excluded.citacao, url = excluded.url, como_foi_lida = excluded.como_foi_lida;
insert into public.referencias (id, citacao, url, como_foi_lida) values ('R5', 'RODRIGUES, V. G. S.; GONZAGA, D. S. O. M. Manjericão (Ocimum basilicum L.). Porto Velho: Embrapa Rondônia, 2001. (Folder Plantas Medicinais, 10).', 'https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/984042/1/foldermanjericao.pdf', 'Lido no original') on conflict (id) do update set citacao = excluded.citacao, url = excluded.url, como_foi_lida = excluded.como_foi_lida;
insert into public.referencias (id, citacao, url, como_foi_lida) values ('R6', 'RODRIGUES, V. G. S.; GONZAGA, D. S. O. M. Hortelã-pimenta (Mentha x piperita L.). Porto Velho: Embrapa Rondônia, 2001. (Folder Plantas Medicinais, 09).', 'https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/984010/1/folderhortelapimenta.pdf', 'Lido no original') on conflict (id) do update set citacao = excluded.citacao, url = excluded.url, como_foi_lida = excluded.como_foi_lida;
insert into public.referencias (id, citacao, url, como_foi_lida) values ('R7', 'BRASIL. Ministério da Agricultura, Pecuária e Abastecimento. Regras para análise de sementes. Brasília: MAPA/ACS, 2009. 399 p.', 'https://www.gov.br/agricultura/pt-br/assuntos/insumos-agropecuarios/arquivos-publicacoes-insumos/2946_regras_analise__sementes.pdf', 'NÃO conferido nesta versão: dias de germinação vêm da memória dos valores de laboratório (1ª e última contagem). Conferir tabela por espécie.') on conflict (id) do update set citacao = excluded.citacao, url = excluded.url, como_foi_lida = excluded.como_foi_lida;
insert into public.especies (id, nome_popular, nome_cientifico, grupo, parte_colhida, propagacao, profundidade_semeadura_cm, germinacao_dias_min, germinacao_dias_max, germinacao_confianca, transplante_dias_apos_semeadura, espacamento_cm, luz_horas_min, local_ideal, luz_confianca, agua_como_regar, agua_confianca, rega_intervalo_dias_min, rega_intervalo_dias_max, solo, adubo_plantio, adubo_cobertura, adubo_confianca, colheita_inicio_dias_min, colheita_inicio_dias_max, colheita_fonte, colheita_confianca, clima_temperatura, dica_acessivel, pendencias) values ('alface', 'Alface', 'Lactuca sativa', 'folhosa', 'folhas', 'muda (sementeira e transplante)', '0,5-1', 4, 7, 'C', '25-35', '25 x 25', 5, 'sol pleno ou meia-sombra', 'A', 'Quase todo dia, de manhã cedo ou fim da tarde. Canteiro: 4 a 10 L/m² aplicados devagar (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C).', 'A', 1, 1, 'Terra fofa, de textura média, bem drenada e rica em matéria orgânica; pH 6,0 a 6,5 (R1 p.3 e p.5). Vaso com no mínimo 20 cm de fundo e furos (R1 p.3; R3 p.25).', 'Canteiro: 3 a 6 kg/m² de esterco bovino curtido + 200 g/m² de NPK 4-14-8 (R1 p.5). Vaso: para 50 L de terra peneirada, 100 g de calcário dolomítico + 34 L de esterco bovino (ou 17 L de esterco de galinha) curtido + 200 g de NPK 4-14-8 (R3 p.26).', '10 a 20 g por planta (ou 20 g/m²) de sulfato de amônio ou NPK 20-5-20 aos 20 a 30 dias, ou 2 kg/m² de esterco/composto (R1 p.10).', 'A', 60, 90, 'R1 Tab.1 (verão: 60-80)', 'A', 'Prefere clima ameno, 18 a 22 °C (R1 p.2); usar cultivar de verão no calor.', 'Use cultivar de verão na época quente. Colha antes de soltar o pendão, senão amarga.', 'Dias de germinação (R7). ''Meia-sombra'' e ''amarga ao pendoar'' são conhecimento geral (C). Ponto de colheita sem fonte lida; procurar em Luengo e Calbo (ed.), Pós-colheita de hortaliças: 500 perguntas, Embrapa, 2011, cap. 9, p. 121.') on conflict (id) do update set nome_popular = excluded.nome_popular, nome_cientifico = excluded.nome_cientifico, grupo = excluded.grupo, parte_colhida = excluded.parte_colhida, propagacao = excluded.propagacao, profundidade_semeadura_cm = excluded.profundidade_semeadura_cm, germinacao_dias_min = excluded.germinacao_dias_min, germinacao_dias_max = excluded.germinacao_dias_max, germinacao_confianca = excluded.germinacao_confianca, transplante_dias_apos_semeadura = excluded.transplante_dias_apos_semeadura, espacamento_cm = excluded.espacamento_cm, luz_horas_min = excluded.luz_horas_min, local_ideal = excluded.local_ideal, luz_confianca = excluded.luz_confianca, agua_como_regar = excluded.agua_como_regar, agua_confianca = excluded.agua_confianca, rega_intervalo_dias_min = excluded.rega_intervalo_dias_min, rega_intervalo_dias_max = excluded.rega_intervalo_dias_max, solo = excluded.solo, adubo_plantio = excluded.adubo_plantio, adubo_cobertura = excluded.adubo_cobertura, adubo_confianca = excluded.adubo_confianca, colheita_inicio_dias_min = excluded.colheita_inicio_dias_min, colheita_inicio_dias_max = excluded.colheita_inicio_dias_max, colheita_fonte = excluded.colheita_fonte, colheita_confianca = excluded.colheita_confianca, clima_temperatura = excluded.clima_temperatura, dica_acessivel = excluded.dica_acessivel, pendencias = excluded.pendencias;
insert into public.especies (id, nome_popular, nome_cientifico, grupo, parte_colhida, propagacao, profundidade_semeadura_cm, germinacao_dias_min, germinacao_dias_max, germinacao_confianca, transplante_dias_apos_semeadura, espacamento_cm, luz_horas_min, local_ideal, luz_confianca, agua_como_regar, agua_confianca, rega_intervalo_dias_min, rega_intervalo_dias_max, solo, adubo_plantio, adubo_cobertura, adubo_confianca, colheita_inicio_dias_min, colheita_inicio_dias_max, colheita_fonte, colheita_confianca, clima_temperatura, dica_acessivel, pendencias) values ('rucula', 'Rúcula', 'Eruca sativa', 'folhosa', 'folhas', 'semeadura direta em linha', '0,5-1', 4, 7, 'C', null, '20 x 15', 5, 'sol pleno ou meia-sombra', 'A', 'Quase todo dia, de manhã cedo ou fim da tarde. Canteiro: 4 a 10 L/m² aplicados devagar (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C).', 'A', 1, 1, 'Terra fofa, de textura média, bem drenada e rica em matéria orgânica; pH 6,0 a 6,5 (R1 p.3 e p.5). Vaso com no mínimo 20 cm de fundo e furos (R1 p.3; R3 p.25).', 'Canteiro: 3 a 6 kg/m² de esterco bovino curtido + 200 g/m² de NPK 4-14-8 (R1 p.5). Vaso: para 50 L de terra peneirada, 100 g de calcário dolomítico + 34 L de esterco bovino (ou 17 L de esterco de galinha) curtido + 200 g de NPK 4-14-8 (R3 p.26).', '10 a 20 g por planta (ou 20 g/m²) de sulfato de amônio ou NPK 20-5-20 aos 20 a 30 dias, ou 2 kg/m² de esterco/composto (R1 p.10).', 'A', 40, 60, 'R2 Tab.8', 'B', 'Prefere clima ameno (R1 p.2). Não recomendada no Norte (R2).', 'Semeie direto no vaso e desbaste deixando 15 cm entre plantas.', 'Ciclo e espaçamento só em R2 (resumo): conferir. Dias de germinação (R7). Ponto de colheita sem fonte lida; procurar em Luengo e Calbo (ed.), Pós-colheita de hortaliças: 500 perguntas, Embrapa, 2011, cap. 9, p. 121.') on conflict (id) do update set nome_popular = excluded.nome_popular, nome_cientifico = excluded.nome_cientifico, grupo = excluded.grupo, parte_colhida = excluded.parte_colhida, propagacao = excluded.propagacao, profundidade_semeadura_cm = excluded.profundidade_semeadura_cm, germinacao_dias_min = excluded.germinacao_dias_min, germinacao_dias_max = excluded.germinacao_dias_max, germinacao_confianca = excluded.germinacao_confianca, transplante_dias_apos_semeadura = excluded.transplante_dias_apos_semeadura, espacamento_cm = excluded.espacamento_cm, luz_horas_min = excluded.luz_horas_min, local_ideal = excluded.local_ideal, luz_confianca = excluded.luz_confianca, agua_como_regar = excluded.agua_como_regar, agua_confianca = excluded.agua_confianca, rega_intervalo_dias_min = excluded.rega_intervalo_dias_min, rega_intervalo_dias_max = excluded.rega_intervalo_dias_max, solo = excluded.solo, adubo_plantio = excluded.adubo_plantio, adubo_cobertura = excluded.adubo_cobertura, adubo_confianca = excluded.adubo_confianca, colheita_inicio_dias_min = excluded.colheita_inicio_dias_min, colheita_inicio_dias_max = excluded.colheita_inicio_dias_max, colheita_fonte = excluded.colheita_fonte, colheita_confianca = excluded.colheita_confianca, clima_temperatura = excluded.clima_temperatura, dica_acessivel = excluded.dica_acessivel, pendencias = excluded.pendencias;
insert into public.especies (id, nome_popular, nome_cientifico, grupo, parte_colhida, propagacao, profundidade_semeadura_cm, germinacao_dias_min, germinacao_dias_max, germinacao_confianca, transplante_dias_apos_semeadura, espacamento_cm, luz_horas_min, local_ideal, luz_confianca, agua_como_regar, agua_confianca, rega_intervalo_dias_min, rega_intervalo_dias_max, solo, adubo_plantio, adubo_cobertura, adubo_confianca, colheita_inicio_dias_min, colheita_inicio_dias_max, colheita_fonte, colheita_confianca, clima_temperatura, dica_acessivel, pendencias) values ('couve', 'Couve-manteiga', 'Brassica oleracea var. acephala', 'folhosa', 'folhas', 'muda de semente ou brotação lateral', '0,5-1,5', 5, 10, 'C', '25-35', '90 x 50', 5, 'sol pleno', 'A', 'Quase todo dia, de manhã cedo ou fim da tarde. Canteiro: 4 a 10 L/m² aplicados devagar (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C).', 'A', 1, 1, 'Terra fofa, de textura média, bem drenada e rica em matéria orgânica; pH 6,0 a 6,5 (R1 p.3 e p.5). Vaso com no mínimo 20 cm de fundo e furos (R1 p.3; R3 p.25).', 'Canteiro: 3 a 6 kg/m² de esterco bovino curtido + 200 g/m² de NPK 4-14-8 (R1 p.5). Vaso: para 50 L de terra peneirada, 100 g de calcário dolomítico + 34 L de esterco bovino (ou 17 L de esterco de galinha) curtido + 200 g de NPK 4-14-8 (R3 p.26).', '10 a 20 g por planta (ou 20 g/m²) de sulfato de amônio ou NPK 20-5-20 aos 20 a 30 dias, ou 2 kg/m² de esterco/composto (R1 p.10); dividir em 2 a 3 aplicações (R1 p.10).', 'A', 70, 90, 'R1 Tab.1', 'A', 'Prefere clima ameno (R1 p.2).', 'Colha as folhas de baixo para cima; a planta produz por meses. Pode ser feita de broto lateral (R3 p.36).', 'Vaso mínimo para couve (sugestão 20-30 L, C). Dias de germinação (R7). Ponto de colheita sem fonte lida; procurar em Luengo e Calbo (ed.), Pós-colheita de hortaliças: 500 perguntas, Embrapa, 2011, cap. 9, p. 121.') on conflict (id) do update set nome_popular = excluded.nome_popular, nome_cientifico = excluded.nome_cientifico, grupo = excluded.grupo, parte_colhida = excluded.parte_colhida, propagacao = excluded.propagacao, profundidade_semeadura_cm = excluded.profundidade_semeadura_cm, germinacao_dias_min = excluded.germinacao_dias_min, germinacao_dias_max = excluded.germinacao_dias_max, germinacao_confianca = excluded.germinacao_confianca, transplante_dias_apos_semeadura = excluded.transplante_dias_apos_semeadura, espacamento_cm = excluded.espacamento_cm, luz_horas_min = excluded.luz_horas_min, local_ideal = excluded.local_ideal, luz_confianca = excluded.luz_confianca, agua_como_regar = excluded.agua_como_regar, agua_confianca = excluded.agua_confianca, rega_intervalo_dias_min = excluded.rega_intervalo_dias_min, rega_intervalo_dias_max = excluded.rega_intervalo_dias_max, solo = excluded.solo, adubo_plantio = excluded.adubo_plantio, adubo_cobertura = excluded.adubo_cobertura, adubo_confianca = excluded.adubo_confianca, colheita_inicio_dias_min = excluded.colheita_inicio_dias_min, colheita_inicio_dias_max = excluded.colheita_inicio_dias_max, colheita_fonte = excluded.colheita_fonte, colheita_confianca = excluded.colheita_confianca, clima_temperatura = excluded.clima_temperatura, dica_acessivel = excluded.dica_acessivel, pendencias = excluded.pendencias;
insert into public.especies (id, nome_popular, nome_cientifico, grupo, parte_colhida, propagacao, profundidade_semeadura_cm, germinacao_dias_min, germinacao_dias_max, germinacao_confianca, transplante_dias_apos_semeadura, espacamento_cm, luz_horas_min, local_ideal, luz_confianca, agua_como_regar, agua_confianca, rega_intervalo_dias_min, rega_intervalo_dias_max, solo, adubo_plantio, adubo_cobertura, adubo_confianca, colheita_inicio_dias_min, colheita_inicio_dias_max, colheita_fonte, colheita_confianca, clima_temperatura, dica_acessivel, pendencias) values ('tomate', 'Tomate (inclui cereja)', 'Solanum lycopersicum', 'fruto', 'frutos', 'muda, transplante aos 25 dias com 4-5 folhas (R4 p.13)', '0,5-1,5', 5, 14, 'C', '25', '100 x 50 (estufa doméstica: 50 x 50, R4)', 5, 'sol pleno', 'A', 'A cada 2 a 3 dias na planta adulta; quase todo dia no início. Canteiro: 4 a 10 L/m²; cova: 3 a 5 L (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C). Molhar só o pé, nunca as folhas (R4 p.13).', 'A', 2, 3, 'Terra fofa, de textura média, bem drenada e rica em matéria orgânica; pH 6,0 a 6,5 (R1 p.3 e p.5). Vaso com no mínimo 20 cm de fundo e furos (R1 p.3; R3 p.25).', 'Canteiro: 3 a 6 kg/m² de esterco bovino curtido + 200 g/m² de NPK 4-14-8 (R1 p.5). Vaso: para 50 L de terra peneirada, 100 g de calcário dolomítico + 34 L de esterco bovino (ou 17 L de esterco de galinha) curtido + 200 g de NPK 4-14-8 (R3 p.26).', '1 kg de esterco curtido por cova no plantio e 300 g de vermicomposto por planta aos 20 dias (R4 p.13). 10 a 20 g por planta (ou 20 g/m²) de sulfato de amônio ou NPK 20-5-20 aos 20 a 30 dias, ou 2 kg/m² de esterco/composto (R1 p.10); dividir em 2 a 3 aplicações (R1 p.10).', 'A', 90, 100, 'R1 Tab.1', 'A', 'Noites frias e úmidas (abaixo de 21 °C) favorecem a requeima (R4 p.10).', 'Amarre a planta num tutor quando tiver 30 cm e tire os brotos laterais de 2 a 5 cm (R4 p.14).', 'Vaso mínimo para tomate (C). R1 dá plantio Abr-Jun no SE e R2 dá o ano todo: conferir. Dias de germinação (R7).') on conflict (id) do update set nome_popular = excluded.nome_popular, nome_cientifico = excluded.nome_cientifico, grupo = excluded.grupo, parte_colhida = excluded.parte_colhida, propagacao = excluded.propagacao, profundidade_semeadura_cm = excluded.profundidade_semeadura_cm, germinacao_dias_min = excluded.germinacao_dias_min, germinacao_dias_max = excluded.germinacao_dias_max, germinacao_confianca = excluded.germinacao_confianca, transplante_dias_apos_semeadura = excluded.transplante_dias_apos_semeadura, espacamento_cm = excluded.espacamento_cm, luz_horas_min = excluded.luz_horas_min, local_ideal = excluded.local_ideal, luz_confianca = excluded.luz_confianca, agua_como_regar = excluded.agua_como_regar, agua_confianca = excluded.agua_confianca, rega_intervalo_dias_min = excluded.rega_intervalo_dias_min, rega_intervalo_dias_max = excluded.rega_intervalo_dias_max, solo = excluded.solo, adubo_plantio = excluded.adubo_plantio, adubo_cobertura = excluded.adubo_cobertura, adubo_confianca = excluded.adubo_confianca, colheita_inicio_dias_min = excluded.colheita_inicio_dias_min, colheita_inicio_dias_max = excluded.colheita_inicio_dias_max, colheita_fonte = excluded.colheita_fonte, colheita_confianca = excluded.colheita_confianca, clima_temperatura = excluded.clima_temperatura, dica_acessivel = excluded.dica_acessivel, pendencias = excluded.pendencias;
insert into public.especies (id, nome_popular, nome_cientifico, grupo, parte_colhida, propagacao, profundidade_semeadura_cm, germinacao_dias_min, germinacao_dias_max, germinacao_confianca, transplante_dias_apos_semeadura, espacamento_cm, luz_horas_min, local_ideal, luz_confianca, agua_como_regar, agua_confianca, rega_intervalo_dias_min, rega_intervalo_dias_max, solo, adubo_plantio, adubo_cobertura, adubo_confianca, colheita_inicio_dias_min, colheita_inicio_dias_max, colheita_fonte, colheita_confianca, clima_temperatura, dica_acessivel, pendencias) values ('pimenta', 'Pimenta', 'Capsicum spp.', 'fruto', 'frutos', 'muda', '0,5-1,5', 7, 14, 'C', '25-35', '120 x 60', 5, 'sol pleno', 'A', 'A cada 2 a 3 dias na planta adulta; quase todo dia no início. Canteiro: 4 a 10 L/m²; cova: 3 a 5 L (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C).', 'A', 2, 3, 'Terra fofa, de textura média, bem drenada e rica em matéria orgânica; pH 6,0 a 6,5 (R1 p.3 e p.5). Vaso com no mínimo 20 cm de fundo e furos (R1 p.3; R3 p.25).', 'Canteiro: 3 a 6 kg/m² de esterco bovino curtido + 200 g/m² de NPK 4-14-8 (R1 p.5). Vaso: para 50 L de terra peneirada, 100 g de calcário dolomítico + 34 L de esterco bovino (ou 17 L de esterco de galinha) curtido + 200 g de NPK 4-14-8 (R3 p.26).', '10 a 20 g por planta (ou 20 g/m²) de sulfato de amônio ou NPK 20-5-20 aos 20 a 30 dias, ou 2 kg/m² de esterco/composto (R1 p.10).', 'A', 100, 120, 'R1 Tab.1', 'A', 'Prefere calor; plantio de primavera-verão (R1, R2).', 'Boa para vaso grande ao sol. Colha os frutos maduros para estimular novos.', 'R3 p.15 chama pimenta de ''dia curto'' e R2 de ''dia neutro'': conferir. Dias de germinação (R7). Ponto de colheita sem fonte lida; procurar em Luengo e Calbo (ed.), Pós-colheita de hortaliças: 500 perguntas, Embrapa, 2011, cap. 9, p. 121.') on conflict (id) do update set nome_popular = excluded.nome_popular, nome_cientifico = excluded.nome_cientifico, grupo = excluded.grupo, parte_colhida = excluded.parte_colhida, propagacao = excluded.propagacao, profundidade_semeadura_cm = excluded.profundidade_semeadura_cm, germinacao_dias_min = excluded.germinacao_dias_min, germinacao_dias_max = excluded.germinacao_dias_max, germinacao_confianca = excluded.germinacao_confianca, transplante_dias_apos_semeadura = excluded.transplante_dias_apos_semeadura, espacamento_cm = excluded.espacamento_cm, luz_horas_min = excluded.luz_horas_min, local_ideal = excluded.local_ideal, luz_confianca = excluded.luz_confianca, agua_como_regar = excluded.agua_como_regar, agua_confianca = excluded.agua_confianca, rega_intervalo_dias_min = excluded.rega_intervalo_dias_min, rega_intervalo_dias_max = excluded.rega_intervalo_dias_max, solo = excluded.solo, adubo_plantio = excluded.adubo_plantio, adubo_cobertura = excluded.adubo_cobertura, adubo_confianca = excluded.adubo_confianca, colheita_inicio_dias_min = excluded.colheita_inicio_dias_min, colheita_inicio_dias_max = excluded.colheita_inicio_dias_max, colheita_fonte = excluded.colheita_fonte, colheita_confianca = excluded.colheita_confianca, clima_temperatura = excluded.clima_temperatura, dica_acessivel = excluded.dica_acessivel, pendencias = excluded.pendencias;
