insert into public.especies (id, nome_popular, nome_cientifico, grupo, parte_colhida, propagacao, profundidade_semeadura_cm, germinacao_dias_min, germinacao_dias_max, germinacao_confianca, transplante_dias_apos_semeadura, espacamento_cm, luz_horas_min, local_ideal, luz_confianca, agua_como_regar, agua_confianca, rega_intervalo_dias_min, rega_intervalo_dias_max, solo, adubo_plantio, adubo_cobertura, adubo_confianca, colheita_inicio_dias_min, colheita_inicio_dias_max, colheita_fonte, colheita_confianca, clima_temperatura, dica_acessivel, pendencias) values ('manjericao', 'Manjericão', 'Ocimum basilicum', 'condimento', 'folhas', 'semente ou estaca (R5)', '0,5-1', 4, 14, 'C', null, '25 x 50', 5, 'sol pleno', 'C', 'Quase todo dia, de manhã cedo ou fim da tarde. Canteiro: 4 a 10 L/m² aplicados devagar (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C).', 'C', 1, 1, 'Terra fofa, de textura média, bem drenada e rica em matéria orgânica; pH 6,0 a 6,5 (R1 p.3 e p.5). Vaso com no mínimo 20 cm de fundo e furos (R1 p.3; R3 p.25).', 'Canteiro: 3 a 6 kg/m² de esterco bovino curtido + 200 g/m² de NPK 4-14-8 (R1 p.5). Vaso: para 50 L de terra peneirada, 100 g de calcário dolomítico + 34 L de esterco bovino (ou 17 L de esterco de galinha) curtido + 200 g de NPK 4-14-8 (R3 p.26).', '10 a 20 g por planta (ou 20 g/m²) de sulfato de amônio ou NPK 20-5-20 aos 20 a 30 dias, ou 2 kg/m² de esterco/composto (R1 p.10).', 'C', null, null, 'R5: colher na floração, de manhã até 11 h', 'A', 'Clima subtropical e temperado quente e úmido (R5).', 'Desbaste 2-3 semanas após germinar e transplante com 3 cm (R5). Adubo: 5 kg de esterco por m² (R5).', 'Dias até primeira colheita, luz e rega específicas: sem fonte. Buscar Embrapa Hortaliças ou extensão (C).') on conflict (id) do update set nome_popular = excluded.nome_popular, nome_cientifico = excluded.nome_cientifico, grupo = excluded.grupo, parte_colhida = excluded.parte_colhida, propagacao = excluded.propagacao, profundidade_semeadura_cm = excluded.profundidade_semeadura_cm, germinacao_dias_min = excluded.germinacao_dias_min, germinacao_dias_max = excluded.germinacao_dias_max, germinacao_confianca = excluded.germinacao_confianca, transplante_dias_apos_semeadura = excluded.transplante_dias_apos_semeadura, espacamento_cm = excluded.espacamento_cm, luz_horas_min = excluded.luz_horas_min, local_ideal = excluded.local_ideal, luz_confianca = excluded.luz_confianca, agua_como_regar = excluded.agua_como_regar, agua_confianca = excluded.agua_confianca, rega_intervalo_dias_min = excluded.rega_intervalo_dias_min, rega_intervalo_dias_max = excluded.rega_intervalo_dias_max, solo = excluded.solo, adubo_plantio = excluded.adubo_plantio, adubo_cobertura = excluded.adubo_cobertura, adubo_confianca = excluded.adubo_confianca, colheita_inicio_dias_min = excluded.colheita_inicio_dias_min, colheita_inicio_dias_max = excluded.colheita_inicio_dias_max, colheita_fonte = excluded.colheita_fonte, colheita_confianca = excluded.colheita_confianca, clima_temperatura = excluded.clima_temperatura, dica_acessivel = excluded.dica_acessivel, pendencias = excluded.pendencias;
