nacao_dias_max, germinacao_confianca = excluded.germinacao_confianca, transplante_dias_apos_semeadura = excluded.transplante_dias_apos_semeadura, espacamento_cm = excluded.espacamento_cm, luz_horas_min = excluded.luz_horas_min, local_ideal = excluded.local_ideal, luz_confianca = excluded.luz_confianca, agua_como_regar = excluded.agua_como_regar, agua_confianca = excluded.agua_confianca, rega_intervalo_dias_min = excluded.rega_intervalo_dias_min, rega_intervalo_dias_max = excluded.rega_intervalo_dias_max, solo = excluded.solo, adubo_plantio = excluded.adubo_plantio, adubo_cobertura = excluded.adubo_cobertura, adubo_confianca = excluded.adubo_confianca, colheita_inicio_dias_min = excluded.colheita_inicio_dias_min, colheita_inicio_dias_max = excluded.colheita_inicio_dias_max, colheita_fonte = excluded.colheita_fonte, colheita_confianca = excluded.colheita_confianca, clima_temperatura = excluded.clima_temperatura, dica_acessivel = excluded.dica_acessivel, pendencias = excluded.pendencias;
insert into public.especies (id, nome_popular, nome_cientifico, grupo, parte_colhida, propagacao, profundidade_semeadura_cm, germinacao_dias_min, germinacao_dias_max, germinacao_confianca, transplante_dias_apos_semeadura, espacamento_cm, luz_horas_min, local_ideal, luz_confianca, agua_como_regar, agua_confianca, rega_intervalo_dias_min, rega_intervalo_dias_max, solo, adubo_plantio, adubo_cobertura, adubo_confianca, colheita_inicio_dias_min, colheita_inicio_dias_max, colheita_fonte, colheita_confianca, clima_temperatura, dica_acessivel, pendencias) values ('morango', 'Morango', 'Fragaria x ananassa', 'fruto', 'frutos', 'muda', null, null, null, null, null, '30 x 20', 5, 'sol pleno', 'A', 'A cada 2 a 3 dias na planta adulta; quase todo dia no início. Canteiro: 4 a 10 L/m²; cova: 3 a 5 L (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C).', 'A', 2, 3, 'Terra fofa, de textura média, bem drenada e rica em matéria orgânica; pH 6,0 a 6,5 (R1 p.3 e p.5). Vaso com no mínimo 20 cm de fundo e furos (R1 p.3; R3 p.25).', 'Canteiro: 3 a 6 kg/m² de esterco bovino curtido + 200 g/m² de NPK 4-14-8 (R1 p.5). Vaso: para 50 L de terra peneirada, 100 g de calcário dolomítico + 34 L de esterco bovino (ou 17 L de esterco de galinha) curtido + 200 g de NPK 4-14-8 (R3 p.26).', '10 a 20 g por planta (ou 20 g/m²) de sulfato de amônio ou NPK 20-5-20 aos 20 a 30 dias, ou 2 kg/m² de esterco/composto (R1 p.10).', 'A', 70, 80, 'R1 Tab.1', 'A', 'Prefere clima ameno; não recomendado no Nordeste e Norte (R2).', 'Compre mudas sadias; não se planta morango por semente em casa. Não deixe os frutos encostarem na terra.', 'Rega do morango em vaso e cobertura do solo (C). Ponto de colheita sem fonte lida; procurar em Luengo e Calbo (ed.), Pós-colheita de hortaliças: 500 perguntas, Embrapa, 2011, cap. 9, p. 121.') on conflict (id) do update set nome_popular = excluded.nome_popular, nome_cientifico = excluded.nome_cientifico, grupo = excluded.grupo, parte_colhida = excluded.parte_colhida, propagacao = excluded.propagacao, profundidade_semeadura_cm = excluded.profundidade_semeadura_cm, germinacao_dias_min = excluded.germinacao_dias_min, germinacao_dias_max = excluded.germinacao_dias_max, germinacao_confianca = excluded.germinacao_confianca, transplante_dias_apos_semeadura = excluded.transplante_dias_apos_semeadura, espacamento_cm = excluded.espacamento_cm, luz_horas_min = excluded.luz_horas_min, local_ideal = excluded.local_ideal, luz_confianca = excluded.luz_confianca, agua_como_regar = excluded.agua_como_regar, agua_confianca = excluded.agua_confianca, rega_intervalo_dias_min = excluded.rega_intervalo_dias_min, rega_intervalo_dias_max = excluded.rega_intervalo_dias_max, solo = excluded.solo, adubo_plantio = excluded.adubo_plantio, adubo_cobertura = excluded.adubo_cobertura, adubo_confianca = excluded.adubo_confianca, colheita_inicio_dias_min = excluded.colheita_inicio_dias_min, colheita_inicio_dias_max = excluded.colheita_inicio_dias_max, colheita_fonte = excluded.colheita_fonte, colheita_confianca = excluded.colheita_confianca, clima_temperatura = excluded.clima_temperatura, dica_acessivel = excluded.dica_acessivel, pendencias = excluded.pendencias;
insert into public.fases (especie_id, ordem, nome, dia_inicio, dia_fim, rega, adubacao, intervencoes, fonte, confianca) values ('alface', 1, 'germinação', 0, 7, 'Manter a terra sempre úmida; regar 2 vezes ao dia, ao amanhecer e no fim da tarde (R3 p.27).', 'Nenhuma.', 'Cobrir sementes com 0,5 a 1,5 cm de terra peneirada (R3 p.27).', 'germinação 4-7 dias: R7 (C)', 'C');
