insert into public.fases (especie_id, ordem, nome, dia_inicio, dia_fim, rega, adubacao, intervencoes, fonte, confianca) values ('alface', 3, 'vegetativo', 35, 60, 'Quase todo dia, de manhã cedo ou fim da tarde. Canteiro: 4 a 10 L/m² aplicados devagar (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C).', 'Cobertura aos 20-30 dias após germinar ou transplantar: 10 a 20 g por planta (ou 20 g/m²) de sulfato de amônio ou NPK 20-5-20 aos 20 a 30 dias, ou 2 kg/m² de esterco/composto (R1 p.10).', 'Tirar mato.', 'R1, R3', 'A');
insert into public.fases (especie_id, ordem, nome, dia_inicio, dia_fim, rega, adubacao, intervencoes, fonte, confianca) values ('alface', 4, 'colheita', 60, 90, 'Quase todo dia, de manhã cedo ou fim da tarde. Canteiro: 4 a 10 L/m² aplicados devagar (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C).', 'Seguir cobertura parcelada em plantas de colheita longa (R1 p.10).', 'Colher no ponto: R1 Tab.1 (verão: 60-80)', 'R1 Tab.1 (verão: 60-80)', 'A');
