insert into public.fases (especie_id, ordem, nome, dia_inicio, dia_fim, rega, adubacao, intervencoes, fonte, confianca) values ('tomate', 3, 'vegetativo', 35, 90, 'A cada 2 a 3 dias na planta adulta; quase todo dia no início. Canteiro: 4 a 10 L/m²; cova: 3 a 5 L (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C). Molhar só o pé, nunca as folhas (R4 p.13).', 'Cobertura aos 20-30 dias após germinar ou transplantar: 1 kg de esterco curtido por cova no plantio e 300 g de vermicomposto por planta aos 20 dias (R4 p.13). 10 a 20 g por planta (ou 20 g/m²) de sulfato de amônio ou NPK 20-5-20 aos 20 a 30 dias, ou 2 kg/m² de esterco/composto (R1 p.10); dividir em 2 a 3 aplicações (R1 p.10).', 'Tirar mato; tutorar quando tiver 30 cm e desbrotar (R4 p.14).', 'R1, R3', 'A');
insert into public.fases (especie_id, ordem, nome, dia_inicio, dia_fim, rega, adubacao, intervencoes, fonte, confianca) values ('tomate', 4, 'colheita', 90, 100, 'A cada 2 a 3 dias na planta adulta; quase todo dia no início. Canteiro: 4 a 10 L/m²; cova: 3 a 5 L (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C). Molhar só o pé, nunca as folhas (R4 p.13).', 'Seguir cobertura parcelada em plantas de colheita longa (R1 p.10).', 'Ponto de colheita: Colher os frutos maduros ou quase maduros. (R1 p.15)', 'R1 Tab.1', 'A');
insert into public.fases (especie_id, ordem, nome, dia_inicio, dia_fim, rega, adubacao, intervencoes, fonte, confianca) values ('pimenta', 1, 'germinação', 0, 14, 'Manter a terra sempre úmida; regar 2 vezes ao dia, ao amanhecer e no fim da tarde (R3 p.27).', 'Nenhuma.', 'Cobrir sementes com 0,5 a 1,5 cm de terra peneirada (R3 p.27).', 'germinação 7-14 dias: R7 (C)', 'C');
insert into public.fases (especie_id, ordem, nome, dia_inicio, dia_fim, rega, adubacao, intervencoes, fonte, confianca) values ('pimenta', 2, 'muda', 14, 35, '1 a 2 vezes ao dia (R3 p.27).', 'Nenhuma até o transplante.', 'Transplantar com 4-6 folhas e 8-10 cm, 25-35 dias após semear, no fim da tarde, e regar (R1 p.8-9).', 'R1', 'A');
insert into public.fases (especie_id, ordem, nome, dia_inicio, dia_fim, rega, adubacao, intervencoes, fonte, confianca) values ('pimenta', 3, 'vegetativo', 35, 100, 'A cada 2 a 3 dias na planta adulta; quase todo dia no início. Canteiro: 4 a 10 L/m²; cova: 3 a 5 L (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C).', 'Cobertura aos 20-30 dias após germinar ou transplantar: 10 a 20 g por planta (ou 20 g/m²) de sulfato de amônio ou NPK 20-5-20 aos 20 a 30 dias, ou 2 kg/m² de esterco/composto (R1 p.10).', 'Tirar mato.', 'R1, R3', 'A');
