insert into public.fases (especie_id, ordem, nome, dia_inicio, dia_fim, rega, adubacao, intervencoes, fonte, confianca) values ('cenoura', 3, 'colheita', 90, 110, 'A cada 2 a 3 dias na planta adulta; quase todo dia no início. Canteiro: 4 a 10 L/m²; cova: 3 a 5 L (R1 p.9). Vaso: regar quando a terra de cima estiver seca ao toque (C).', 'Seguir cobertura parcelada em plantas de colheita longa (R1 p.10).', 'Ponto de colheita: Colher quando a raiz estiver bem desenvolvida, antes de ficar fibrosa e antes de a planta pendoar (soltar a haste de flor). (R1 p.15)', 'R1 Tab.1', 'A');
